using System.IO.Compression;using System.Reflection;using System.Security.Cryptography;using System.Text.Json;using TerraRuntime.Core;using TerraRuntime.Core.Npcs;using TerraRuntime.Core.Projectiles;using TerraRuntime.Core.Worlds.Generation;using TerraRuntime.World;
namespace TerraRuntime.Tests;
public sealed class GenerationSmoothGap1458Tests {
 private static readonly JsonDocument Source=Load();
 public static IEnumerable<object[]> Cases(){foreach(var r in Source.RootElement.GetProperty("cases").EnumerateArray())yield return [r.GetProperty("terrain").GetUInt16(),r.GetProperty("objectKind").GetInt32(),r.GetProperty("layout").GetInt32(),r.GetProperty("seed").GetInt32(),r.GetProperty("pose").GetInt32()];}
 [Theory,MemberData(nameof(Cases))]
 public void Registered_SmoothWorld_gap_placement_preserves_source_callbacks(ushort terrain,int objectKind,int layout,int seed,int pose){
  var row=Source.RootElement.GetProperty("cases").EnumerateArray().Single(r=>r.GetProperty("terrain").GetUInt16()==terrain&&r.GetProperty("objectKind").GetInt32()==objectKind&&r.GetProperty("layout").GetInt32()==layout&&r.GetProperty("seed").GetInt32()==seed&&r.GetProperty("pose").GetInt32()==pose);var world=new Workspace(96,96);world.InitializeVanillaGenerationSolidity();int index=0;foreach(var value in Source.RootElement.GetProperty("entrySolidity").EnumerateArray())world.SetVanillaGenerationSolid(new((ushort)index++),value.GetBoolean());var npcs=new RuntimeNpcStore();var projectiles=new RuntimeProjectileStore();var effects=new WorldGenerationEntityEffects1458(npcs,projectiles,true);world.AttachEntityEffects(effects,0);if(pose>=0){var p=Source.RootElement.GetProperty("npcPoses")[pose];Assert.True(effects.RetainTownNpc(new(37),800+p.GetProperty("x").GetSingle(),800+p.GetProperty("y").GetSingle(),true,0,0,out _));}
  void Set(int x,int y,ushort type){var tile=new WorldTile{Type=type,Flags=WorldTileFlags.Active};world.TileStore.Set(x,y,in tile);}int side=layout==1?-1:1;Set(50,51,terrain);Set(50-side,51,1);Set(50+side,50,1);if(layout==2){var tile=world.TileStore.Get(50-side,51);tile.Flags&=~WorldTileFlags.Active;world.TileStore.Set(50-side,51,in tile);}var anchor=new WorldTile{Type=191,FrameX=-1,FrameY=-1,Wall=1,TileColor=7,Flags=WorldTileFlags.WireRed|WorldTileFlags.InvisibleBlock|WorldTileFlags.FullbrightBlock};world.TileStore.Set(50,50,in anchor);if(objectKind>0){ushort kind=objectKind==1||objectKind==2?(ushort)26:objectKind==3?(ushort)15:objectKind==4?(ushort)187:objectKind==5?(ushort)4:(ushort)129;Set(50-side,49,kind);if(objectKind==2){var tile=world.TileStore.Get(50-side,49);tile.FrameX=54;world.TileStore.Set(50-side,49,in tile);}}
  if(layout==3){var tile=world.TileStore.Get(50,50);tile.TrySetSourceShape(true,3);world.TileStore.Set(50,50,in tile);}if(layout==4){var tile=world.TileStore.Get(50,50);tile.Flags|=WorldTileFlags.Actuator|WorldTileFlags.Inactive;world.TileStore.Set(50,50,in tile);}if(objectKind==6)Set(50-2*side,49,1);
  var random=new RandomAdapter(seed);WorldSmoother1458.Apply(world,random,TestContext.Current.CancellationToken);var expected=row.GetProperty("capture");Assert.Equal(expected.GetProperty("gridHash").GetString(),GenerationNaturalPrefix49Tests.GridHash(world));var physical=expected.GetProperty("random");using var stream=new MemoryStream();using(var writer=new BinaryWriter(stream,System.Text.Encoding.UTF8,true)){writer.Write(physical.GetProperty("cursor").GetUInt32());foreach(var slot in physical.GetProperty("slots").EnumerateArray())writer.Write(slot.GetInt32());}Assert.Equal(Convert.ToHexString(SHA256.HashData(stream.ToArray())),GenerationNaturalPrefix49Tests.RandomHash(random,includeReport:false));Assert.Equal(physical.GetProperty("next").GetInt32(),random.PeekNext());Assert.Equal(Source.RootElement.GetProperty("exitSolidity").EnumerateArray().Select(a=>a.GetBoolean()),Enumerable.Range(0,754).Select(i=>world.IsVanillaGenerationSolid(new((ushort)i))));Assert.Empty(row.GetProperty("effects").EnumerateArray());Assert.Equal(0,projectiles.ActiveCount);Assert.Equal(row.GetProperty("npcs").GetArrayLength(),npcs.ActiveCount);foreach(var n in row.GetProperty("npcs").EnumerateArray()){Assert.True(npcs.TryGetActive(n.GetProperty("slot").GetByte(),out var npc));Assert.Equal(n.GetProperty("type").GetInt32(),npc.Type);Assert.Equal(n.GetProperty("x").GetSingle(),npc.PositionX);Assert.Equal(n.GetProperty("y").GetSingle(),npc.PositionY);Assert.True(TerraRuntime.Gameplay.Npcs.VanillaNpcDefinitionCatalog.TryGet(npc.TypeIdentity,out var definition));Assert.True(definition.TryResolveHitbox(npc.Simulation,out var body));Assert.Equal(n.GetProperty("width").GetInt32(),body.Width);Assert.Equal(n.GetProperty("height").GetInt32(),body.Height);}
 }
 [Fact]
 public void Solid_gap_requires_explicit_canonical_NPC_owner(){
  var world=new Workspace(96,96);world.InitializeVanillaGenerationSolidity();int index=0;foreach(var value in Source.RootElement.GetProperty("entrySolidity").EnumerateArray())world.SetVanillaGenerationSolid(new((ushort)index++),value.GetBoolean());
  void Set(int x,int y){var tile=new WorldTile{Type=1,Flags=WorldTileFlags.Active};world.TileStore.Set(x,y,in tile);}Set(50,51);Set(49,51);Set(51,50);var random=new RandomAdapter(1);var token=TestContext.Current.CancellationToken;var error=Assert.Throws<NotSupportedException>(()=>WorldSmoother1458.Apply(world,random,token));Assert.Contains("canonical generation NPC owner",error.Message);
 }
 private static JsonDocument Load(){using var raw=typeof(GenerationSmoothGap1458Tests).Assembly.GetManifestResourceStream("GenerationSmoothGap1458")!;using var gzip=new GZipStream(raw,CompressionMode.Decompress);return JsonDocument.Parse(gzip);}
    private sealed class RandomAdapter(int seed) : IWorldGenerationVanillaRandom
    {
        private readonly VanillaUnifiedRandom1458 random = new(seed);
        public int PeekNext()
        {
            const BindingFlags fields = BindingFlags.Instance | BindingFlags.NonPublic;
            var clone = new VanillaUnifiedRandom1458(0); var cursor = typeof(VanillaUnifiedRandom1458).GetField("inext", fields)!; var slots = typeof(VanillaUnifiedRandom1458).GetField("seedArray", fields)!;
            cursor.SetValue(clone, cursor.GetValue(random)); Array.Copy((int[])slots.GetValue(random)!, (int[])slots.GetValue(clone)!, 56); return clone.Next();
        }
        public int Next() => random.Next(); public int Next(int max) => random.Next(max); public int Next(int min, int max) => random.Next(min, max); public double NextDouble() => random.NextDouble(); public void NextBytes(byte[] bytes) => random.NextBytes(bytes);
    }
}
